window.ME_DATA["y11-me"] = [
 {
  id:"l1", lesson:1, title:"ما معنى «الاقتصاد» و«العولمة»؟", unit:"الوحدة الأولى: الأخلاق والاقتصاد العالمي", art:"globe",
  dna:"انظر إلى الملصقات على ثلاثة أشياء تحملها معك اليوم (الملابس، الهاتف، الأدوات المكتبية، تغليف الطعام). اكتب أين صُنع كل منها أو زُرع. ماذا يخبرك ذلك عن مدى ترابط اقتصادات العالم؟",
  dnaQs:["أين صُنعت أو زُرعت ثلاثة من الأشياء التي تحملها معك اليوم؟","كم دولة مختلفة شاركت في ذلك؟","ماذا يخبرك ذلك عن مدى ترابط اقتصادات العالم؟"],
  dnaHint:"الإجابة الجيدة تذكر دولًا حقيقية من الملصقات (مثل هاتف جُمِّع في دولة باستخدام قطع من دول أخرى عدة)، وتلاحظ أن قلة قليلة من الأشياء اليومية تُصنع بالكامل في مكان واحد، وتربط ذلك بفكرة أن الاقتصادات مترابطة ويعتمد بعضها على بعض: فما يحدث في دولة يؤثر في غيرها.",
  intentions:["أن أفهم المقصود بـ«الاقتصاد» و«العولمة».","أن أستكشف المحركات الرئيسة للعولمة، مثل التجارة والتكنولوجيا والنقل والاتصالات.","أن أحلل كيف يرتبط اقتصاد دولة الإمارات بالاقتصاد العالمي."],
  criteria:["أستطيع أن أعرّف «الاقتصاد» و«العولمة» تعريفًا دقيقًا بأسلوبي الخاص.","أستطيع أن أشرح ثلاثة محركات للعولمة على الأقل مع أمثلة.","أستطيع أن أحلل كيف تشارك دولة الإمارات في الاقتصاد العالمي وتعتمد عليه."],
  concept:{key:"التفاعلات العالمية", related:"الاعتماد المتبادل، الأنظمة", soi:"تزداد الأنظمة الاقتصادية اعتمادًا بعضها على بعض، ولذلك فإن لخيارات الأفراد والشركات والدول عواقب تمتد إلى ما هو أبعد من حدودها بكثير.", context:"العولمة والاستدامة — استكشاف كيف تربط التجارة والتكنولوجيا والاتصالات بين الناس والاقتصادات في أنحاء العالم.", uae:"دور دولة الإمارات مركزًا عالميًا للتجارة والخدمات اللوجستية (ميناء جبل علي، ومطارا دبي وأبوظبي)، وتنويعها الاقتصادي بعيدًا عن النفط، واتفاقيات الشراكة الاقتصادية الشاملة (CEPA)؛ مع روابط بمادتي الأفراد والمجتمعات (الاقتصاد) والجغرافيا."},
  words:[["الاقتصاد (Economy)","النظام الذي تنتج به دولة أو منطقة السلع والخدمات وتوزعها وتستهلكها."],["العولمة (Globalisation)","العملية التي تصبح بها الاقتصادات والثقافات والشعوب في أنحاء العالم أكثر ترابطًا واعتمادًا بعضها على بعض."],["الاعتماد المتبادل (Interdependence)","حالة تعتمد فيها الدول أو الأشخاص بعضهم على بعض، بحيث يؤثر التغير في أحدهم في الآخرين."],["التجارة (Trade)","بيع السلع والخدمات وشراؤها، بما في ذلك بين الدول (الواردات والصادرات)."],["سلسلة التوريد (Supply chain)","تسلسل الخطوات والأماكن المشاركة في إنتاج منتج ما وإيصاله إلى المستهلك."],["التنويع الاقتصادي (Diversification)","توسيع الاقتصاد ليشمل مجموعة أوسع من القطاعات لتقليل الاعتماد على قطاع واحد، مثل النفط."]],
  task1:{title:"مهمة البحث", mins:20, criterion:"المعيار B — البحث والاستقصاء", steps:["اختر منتجًا يوميًا واحدًا (مثل هاتف ذكي، أو قميص قطني، أو لوح شوكولاتة، أو حذاء رياضي).","ابحث في سلسلة توريده مستخدمًا مصدرين موثوقين على الأقل.","سجّل: من أين تأتي مواده الخام، وأين يُصنع أو يُجمَّع، وكيف يصل إلى المستهلكين في دولة الإمارات.","حدد محركات العولمة (التجارة، التكنولوجيا، النقل، الاتصالات) التي تجعل سلسلة التوريد هذه ممكنة."], prompts:["المنتج الذي اخترته ومصدراي","من أين تأتي المواد الخام","أين يُصنع أو يُجمَّع، وكيف يصل إلى دولة الإمارات","محركات العولمة التي تجعل سلسلة التوريد هذه ممكنة"], success:"الإجابات القوية تتتبع سلسلة توريد حقيقية عبر مراحل ودول عدة (مثل كاكاو يُزرع في غرب أفريقيا، ويُصنَّع في أوروبا، ويُباع في دبي) بدلًا من ذكر دولة واحدة. وهي تربط مراحل محددة بمحركات محددة، مثل الشحن بالحاويات (النقل)، والطلب والتتبع عبر الإنترنت (التكنولوجيا والاتصالات)، والاتفاقيات التجارية (التجارة). وللوصول إلى أعلى مستوى، استخدم مصدرين موثوقين وعلّق على مدى الاعتماد المتبادل في سلسلة التوريد: ماذا يحدث لو تعطلت إحدى المراحل؟"},
  task2:{title:"مهمة القراءة والكتابة", mins:25, criterion:"المعيار C — التواصل", extract:"تطلب أسرة في دبي أريكة عبر الإنترنت. صُمِّمت الأريكة في السويد، وصُنعت من خشب نما في أوروبا الشرقية وقماش نُسج في آسيا، وجُمِّعت في دولة أخرى، ثم شُحنت عبر ميناء جبل علي وسُلِّمت خلال أسبوع.", steps:["في فقرة منظمة (جملة افتتاحية، شرح، مثال، خاتمة)، اشرح كيف يوضح هذا المقتطف مفهوم العولمة.","استخدم ثلاث كلمات على الأقل من بنك الكلمات (مثل العولمة، سلسلة التوريد، الاعتماد المتبادل) استخدامًا دقيقًا.","اختم بتقييم ما إذا كان هذا المستوى من الاعتماد المتبادل يجعل الاقتصادات أقوى أم أكثر عرضة للخطر."], model:"الأريكة في المقتطف مثال واضح على العولمة، لأن منتجًا واحدًا يربط بين المصممين ومنتجي المواد الخام والمصنّعين والمستهلكين في دول مختلفة عدة. وتعتمد سلسلة توريدها على التجارة بين الدول، وعلى التكنولوجيا التي تتيح للأسرة الطلب عبر الإنترنت، وعلى البنية التحتية للنقل مثل ميناء جبل علي. ويبيّن ذلك الاعتماد المتبادل بين الاقتصادات الحديثة: فالأسرة في دبي تعتمد على عمال لن تلتقي بهم أبدًا، وهؤلاء العمال يعتمدون على المستهلكين في الخارج لكسب دخلهم. وبعد الموازنة، أرى أن هذا الاعتماد المتبادل يجعل الاقتصادات أقوى لأنه يتيح الوصول إلى مزيد من السلع والأسواق، لكنه يجعلها أيضًا أكثر عرضة للخطر، لأن تعطل مرحلة واحدة، مثل إغلاق أحد طرق الشحن، قد يؤخر المنتجات في أنحاء العالم.", rubric:[["1–2","بنية محدودة؛ استخدام قليل أو معدوم للمفردات الرئيسة."],["3–4","بنية فقرة أساسية؛ استخدام مصطلح رئيس واحد، وربما بصورة غير دقيقة."],["5–6","بنية فقرة واضحة؛ استخدام 2–3 مصطلحات رئيسة بدقة في معظم الأحيان؛ بعض التقييم."],["7–8","فقرة محكمة البنية؛ استخدام 3 مصطلحات رئيسة أو أكثر بدقة؛ تقييم متوازن ومبرر تبريرًا جيدًا."]], starters:["تُعدّ الأريكة مثالًا على العولمة لأن ___.","تعتمد سلسلة توريدها على ___ و___.","يبيّن ذلك الاعتماد المتبادل لأن ___.","بعد الموازنة، يجعل الاعتماد المتبادل الاقتصادات ___ لأن ___."]},
  task3:{title:"مهمة المشروع", mins:"حصتان", criterion:"المعيار D — التفكير الناقد", name:"دولة الإمارات في الاقتصاد العالمي", steps:["في مجموعات من 3–4 طلاب، صمموا إنفوجرافيك يوضح كيف ترتبط دولة الإمارات بالاقتصاد العالمي.","ضمّنوا أربعة روابط على الأقل (مثل الموانئ والمطارات، والسياحة، والعمالة والاستثمارات الأجنبية، والاتفاقيات التجارية، والصادرات غير النفطية).","لكل رابط، اشرحوا طريقة واحدة تستفيد بها دولة الإمارات، وطريقة واحدة تعتمد فيها على دول أخرى.","حددوا حدثًا عالميًا واحدًا قد يعطّل أحد هذه الروابط، وكيف يمكن أن تستجيب دولة الإمارات له.","اعرضوا الإنفوجرافيك على الصف في عرض مدته 3 دقائق، واستخدموا مفردات بنك الكلمات في عرضكم."], rubric:[["1–2","تحديد روابط قليلة؛ شرح محدود."],["3–4","تحديد بعض الروابط؛ وصف الفوائد والاعتماد بصورة مبهمة."],["5–6","أربعة روابط واضحة مع فوائد واعتماد دقيقين؛ تحديد حدث معطِّل."],["7–8","روابط عميقة ودقيقة؛ تحليل مدروس للفوائد والاعتماد؛ استجابة واقعية ومعللة جيدًا للتعطل."]]},
  game:{type:"sort", title:"أي محرك للعولمة؟", prompt:"صنّف كل مثال تحت محرك العولمة الذي يمثله على أفضل وجه.", bins:["التجارة","التكنولوجيا والاتصالات","النقل"], items:[["اتفاقية تجارية تخفض الضرائب على الواردات بين دولتين",0],["سفن حاويات تحمل آلاف السلع عبر المحيطات",2],["مكالمات فيديو تتيح لفريق في دبي العمل مع فريق في سنغافورة",1],["دولة تصدّر الألمنيوم وتستورد السيارات",0],["شركة طيران للرحلات الطويلة تربط مدنًا في قارات مختلفة",2],["متجر إلكتروني يوصل الطلبات إلى عملاء في دول كثيرة",1],["وسائل التواصل الاجتماعي تنشر صيحة حول العالم خلال ساعات",1],["منطقة حرة تجذب الشركات الأجنبية لافتتاح مكاتب فيها",0]]},
  quiz:[["ما «الاقتصاد»؟",["شركة واحدة تبيع السلع في الخارج","النظام الذي تنتج به دولة أو منطقة السلع والخدمات وتوزعها وتستهلكها","نوع من الضرائب يُدفع على الواردات"],1],["أي تعريف يصف «العولمة» على أفضل وجه؟",["إغلاق الدول حدودها أمام التجارة","انتشار مطاعم الوجبات السريعة فقط","العملية التي تصبح بها الاقتصادات والثقافات والشعوب أكثر ترابطًا واعتمادًا بعضها على بعض"],2],["ما معنى «الاعتماد المتبادل»؟",["اعتماد الدول أو الأشخاص بعضهم على بعض، بحيث يؤثر التغير في أحدهم في الآخرين","اكتفاء دولة ما ذاتيًا اكتفاءً تامًا","تنافس دولتين في الرياضة"],0],["ما «سلسلة التوريد»؟",["سلسلة تُستخدم لإقفال مستودع","قائمة بأسعار متجر ما","تسلسل الخطوات والأماكن المشاركة في إنتاج منتج ما وإيصاله"],2],["أي مما يلي يُعدّ محركًا للعولمة؟",["تطور النقل، مثل الشحن بالحاويات والسفر الجوي","تراجع استخدام الإنترنت","قلة الاتفاقيات التجارية"],0],["لماذا اتجهت دولة الإمارات إلى التنويع الاقتصادي؟",["لوقف التجارة كلها مع الدول الأخرى","لتقليل اعتمادها على قطاع واحد، مثل النفط","لجعل المنتجات أغلى ثمنًا"],1],["في مقتطف الأريكة، علامَ يدل ميناء جبل علي؟",["استوديو تصميم","مادة خام","بنية تحتية للنقل تربط دولة الإمارات بالتجارة العالمية"],2],["ما أحد مخاطر الاقتصاد العالمي شديد الاعتماد المتبادل؟",["يستطيع المستهلكون شراء مزيد من المنتجات","قد يؤثر تعطل في مكان واحد في سلاسل التوريد حول العالم","تستطيع الدول التخصص فيما تجيده"],1]],
  exit:"في جملة واحدة، اشرح كيف يربطك شيء واحد تملكه بأشخاص في دولة أخرى.",
  copy:{facts:["الاقتصاد هو النظام الذي تُنتَج به السلع والخدمات وتُوزَّع وتُستهلَك.","العولمة هي الترابط والاعتماد المتبادل المتزايد بين الاقتصادات والثقافات والشعوب، وتحركها التجارة والتكنولوجيا والنقل والاتصالات.","دولة الإمارات مركز عالمي للتجارة والخدمات اللوجستية، وهي تنوّع اقتصادها بعيدًا عن النفط."]},
  next:"الحصة القادمة: نتابع الوحدة الأولى بالموازنة بين فوائد العولمة وسلبياتها."
 },
 {
  id:"l2", lesson:2, title:"فوائد العولمة وسلبياتها", unit:"الوحدة الأولى: الأخلاق والاقتصاد العالمي", art:"reason",
  dna:"مراجعة: في جملة واحدة، عرّف «العولمة» كما تعلمتها في الحصة السابقة. ثم فكّر: اذكر طريقة واحدة تجعل بها العولمة حياتك أفضل، وطريقة واحدة قد تُلحق بها الضرر بشخص ما في مكان ما.",
  dnaQs:["في جملة واحدة، ما العولمة؟","اذكر طريقة واحدة تجعل بها العولمة حياتك أفضل.","اذكر طريقة واحدة قد تُلحق بها العولمة الضرر بشخص ما في مكان ما."],
  dnaHint:"العولمة هي الترابط والاعتماد المتبادل المتزايد بين الاقتصادات والثقافات والشعوب. ومن فوائدها إتاحة مجموعة واسعة من المنتجات بأسعار معقولة، أو فرص العمل، أو التبادل الثقافي. ومن أضرارها تدني الأجور في المصانع، أو الضرر البيئي الناتج عن الشحن، أو معاناة الأعمال المحلية في المنافسة.",
  intentions:["أن أفهم الفوائد والسلبيات الاقتصادية والاجتماعية والثقافية والبيئية الرئيسة للعولمة.","أن أستكشف كيف يمكن أن تؤثر العولمة في فئات مختلفة من الناس بطرق مختلفة.","أن أقيّم ما إذا كانت فوائد العولمة تفوق سلبياتها، مستخدمًا التفكير الأخلاقي."],
  criteria:["أستطيع أن أشرح فوائد العولمة وسلبياتها في مجالات مختلفة من الحياة.","أستطيع أن أحلل كيف تُوجِد العولمة «رابحين» و«خاسرين» بين الفئات المختلفة.","أستطيع أن أصل إلى حكم متوازن ومبرر بشأن العولمة."],
  concept:{key:"التفاعلات العالمية", related:"وجهة النظر، العواقب", soi:"تجلب العولمة فرصًا وتكاليف معًا، ويتوقف أثرها الأخلاقي على وجهة النظر التي نأخذها في الحسبان.", context:"العولمة والاستدامة — استكشاف الآثار غير المتكافئة للترابط الاقتصادي العالمي على الناس وكوكب الأرض.", uae:"مجتمع دولة الإمارات المنفتح ومتعدد الثقافات الذي يضم مقيمين من جنسيات كثيرة، والتزام الدولة بالحفاظ على التراث الوطني والهوية العربية إلى جانب التأثير العالمي، ومبادرة الإمارات للحياد المناخي 2050؛ مع روابط بمادتي الأفراد والمجتمعات والعلوم (الأثر البيئي)."},
  words:[["الفائدة (Benefit)","ميزة أو أثر إيجابي يُكتسب من شيء ما."],["السلبية (Drawback)","عيب أو مشكلة تجعل الشيء أقل قبولًا."],["الاستعانة بمصادر خارجية (Outsourcing)","نقل شركة ما للعمل أو الإنتاج إلى شركة أو دولة أخرى، غالبًا لخفض التكاليف."],["التجانس الثقافي (Cultural homogenisation)","العملية التي تصبح بها الثقافات المحلية أكثر تشابهًا، وغالبًا ما تفقد تقاليدها المميزة."],["الاستغلال (Exploitation)","معاملة الناس معاملة غير عادلة للاستفادة من عملهم، كدفع أجور متدنية جدًا أو توفير ظروف عمل غير آمنة."],["وجهة النظر (Perspective)","رأي معين يتشكل من موقع الشخص أو تجربته أو مصالحه."]],
  task1:{title:"مهمة البحث", mins:20, criterion:"المعيار B — البحث والاستقصاء", steps:["اختر مثالًا حقيقيًا واحدًا على أثر العولمة (مثل نمو صناعة تحويلية في دولة آسيوية، أو سلاسل الوجبات السريعة العالمية، أو صناعة السياحة العالمية، أو الشحن الدولي).","ابحث فيه مستخدمًا مصدرين موثوقين على الأقل.","سجّل: فائدة واحدة وسلبية واحدة لهذا المثال، ومَن يتأثر بكل منهما.","دوّن إجراءً واحدًا اتُّخذ (من حكومة أو شركة أو منظمة) للحد من السلبية."], prompts:["المثال الذي اخترته ومصدراي","فائدة واحدة، ومَن يستفيد منها","سلبية واحدة، ومَن يتأثر بها","إجراء واحد اتُّخذ للحد من السلبية"], success:"الإجابات القوية تحدد فئات بعينها متأثرة (مثل عمال المصانع، وأصحاب المتاجر المحلية، والمستهلكين، والأجيال القادمة) بدلًا من قول «الناس» بشكل عام، وتدرك أن التطور نفسه قد يفيد فئة ويضر بأخرى. فعلى سبيل المثال، قد توفر صناعة الملابس فرص عمل وترفع الدخل، لكنها قد تنطوي أيضًا على ساعات عمل طويلة أو ظروف غير آمنة. وللوصول إلى أعلى مستوى، استخدم مصدرين موثوقين واشرح استجابة حقيقية، مثل قوانين سلامة أكثر صرامة أو اتفاقيات على مستوى القطاع."},
  task2:{title:"مهمة القراءة والكتابة", mins:25, criterion:"المعيار C — التواصل", extract:"تفتتح شركة ملابس دولية كبيرة مصنعًا في دولة نامية. يحصل آلاف السكان المحليين على وظائف، لكن الأجور متدنية وساعات العمل طويلة. وفي الوقت نفسه، يُغلق مصنع ملابس محلي في دولة أكثر ثراءً لأنه لا يستطيع المنافسة في السعر.", steps:["في فقرة منظمة (جملة افتتاحية، شرح، مثال، خاتمة)، حلّل مَن يستفيد ومَن يخسر من الموقف الوارد في المقتطف.","استخدم ثلاث كلمات على الأقل من بنك الكلمات (مثل الاستعانة بمصادر خارجية، الاستغلال، وجهة النظر) استخدامًا دقيقًا.","اختم بحكم مبرر: هل هذا المثال على العولمة أخلاقي في مجمله؟"], model:"يبيّن المقتطف أن العولمة قد تُوجِد رابحين وخاسرين معًا، تبعًا لوجهة النظر التي نأخذها في الحسبان. فمن خلال الاستعانة بمصادر خارجية، تستفيد الشركة من انخفاض التكاليف، ويستفيد المستهلكون من الملابس الأرخص، بينما يحصل آلاف العمال في الدولة النامية على وظائف ربما لم تكن لتوجد لولا ذلك. غير أن الأجور المتدنية وساعات العمل الطويلة تثير مخاوف من الاستغلال، كما يفقد العمال في الدولة الأكثر ثراءً مصادر رزقهم عند إغلاق المصنع المحلي. وفي رأيي، هذا المثال ليس أخلاقيًا تمامًا بوضعه الحالي، لأن الشركة تجني الأرباح بينما يتحمل العمال معظم التكاليف؛ ويمكن أن يصبح أكثر أخلاقية إذا دفعت الشركة أجورًا عادلة وضمنت ظروف عمل آمنة ومعقولة. (يمكن أن تنال استنتاجات أخرى الدرجة الكاملة إذا كانت مبررة تبريرًا جيدًا.)", rubric:[["1–2","بنية محدودة؛ استخدام قليل أو معدوم للمفردات الرئيسة."],["3–4","بنية فقرة أساسية؛ استخدام مصطلح رئيس واحد، وربما بصورة غير دقيقة؛ معالجة من جانب واحد."],["5–6","بنية فقرة واضحة؛ استخدام 2–3 مصطلحات رئيسة بدقة في معظم الأحيان؛ مراعاة أكثر من وجهة نظر."],["7–8","فقرة محكمة البنية؛ استخدام 3 مصطلحات رئيسة أو أكثر بدقة؛ تحليل وجهات نظر متعددة؛ حكم مبرر تبريرًا جيدًا."]], starters:["من وجهة نظر ___، تجلب العولمة ___.","ومع ذلك، قد يتعرض ___ للاستغلال لأن ___.","تفيد الاستعانة بمصادر خارجية ___ لكنها تضر بـ ___.","في رأيي، هذا المثال أخلاقي / غير أخلاقي في مجمله لأن ___."]},
  task3:{title:"مهمة المشروع", mins:"حصتان", criterion:"المعيار D — التفكير الناقد", name:"مناظرة حول العولمة", steps:["في مجموعات من 3–4 طلاب، سيُحدَّد لكم موقف من القضية: «يرى هذا المجلس أن فوائد العولمة تفوق سلبياتها».","أعدّوا ثلاث حجج لموقفكم، تدعم كلًا منها بمثال حقيقي من بحثكم.","توقعوا حجتين سيطرحهما الفريق الآخر، وأعدّوا ردودًا عليهما.","ضمّنوا حجة واحدة على الأقل تراعي منظورًا أخلاقيًا (العدالة، أو حقوق العمال، أو البيئة، أو الهوية الثقافية).","شاركوا في مناظرة صفية منظمة، ثم اكتبوا تأملًا شخصيًا قصيرًا حول الموقف الذي وجدتموه أكثر إقناعًا ولماذا."], rubric:[["1–2","حجج غير مكتملة وغير مدعومة بأمثلة."],["3–4","حجج أساسية مع أمثلة محدودة؛ ردود قليلة."],["5–6","حجج واضحة مدعومة بأمثلة ذات صلة؛ ردود معقولة؛ تضمين منظور أخلاقي."],["7–8","حجج متقدمة ومدعومة بأدلة قوية؛ ردود قوية؛ تفكير أخلاقي عميق؛ تأمل يُظهر تفاعلًا حقيقيًا مع الموقفين."]]},
  game:{type:"sort", title:"فائدة أم سلبية؟", prompt:"صنّف كل أثر من آثار العولمة: هل يُعدّ عادةً فائدة أم سلبية؟", bins:["فائدة","سلبية"], items:[["يستطيع المستهلكون شراء مجموعة أوسع من السلع بأسعار أقل",0],["يواجه العمال في بعض المصانع أجورًا متدنية وظروفًا غير آمنة",1],["تنتشر الأفكار والأدوية والتقنيات الجديدة بسرعة بين الدول",0],["تكافح التقاليد المحلية والأعمال الصغيرة من أجل البقاء",1],["تزيد كثرة الشحن والرحلات الجوية من انبعاثات الكربون",1],["يوفر الاستثمار الأجنبي فرص عمل في الاقتصادات النامية",0],["يتعلم أناس من ثقافات مختلفة بعضهم من بعض ويتفاهمون",0],["تنتقل الوظائف إلى الخارج، فتبقى بعض المجتمعات بلا عمل",1]]},
  quiz:[["ما «الاستعانة بمصادر خارجية»؟",["نقل العمل أو الإنتاج إلى شركة أو دولة أخرى، غالبًا لخفض التكاليف","شراء المنتجات المحلية فقط","إغلاق شركة بالكامل"],0],["ما معنى «التجانس الثقافي»؟",["الاحتفاء بثقافات كثيرة مختلفة","أن تصبح الثقافات المحلية أكثر تشابهًا وتفقد تقاليدها المميزة","نوع من الطهي"],1],["أي مما يلي سلبية بيئية للعولمة؟",["المنتجات الأرخص","سرعة الاتصالات","انبعاثات الكربون الناتجة عن نقل السلع حول العالم"],2],["ما معنى «الاستغلال» في السياق الاقتصادي؟",["معاملة الناس معاملة غير عادلة للاستفادة من عملهم، كدفع أجور متدنية جدًا","استكشاف دول جديدة","الاستثمار في شركة"],0],["لماذا من المهم مراعاة «وجهة النظر» عند الحكم على العولمة؟",["لأن الجميع يتأثرون بالطريقة نفسها تمامًا","لأن التغيير نفسه قد يفيد فئة ويضر بأخرى","لأن آراء الحكومات وحدها هي المهمة"],1],["في المقتطف، مَن يخسر عند إغلاق المصنع المحلي؟",["المستهلكون الذين يشترون ملابس أرخص","الشركة الدولية","العمال في الدولة الأكثر ثراءً"],2],["أي مما يلي مثال على فائدة من فوائد العولمة؟",["انتشار الأدوية والتقنيات بسرعة بين الدول","اختفاء الوظائف من أحد المجتمعات","ظروف المصانع غير الآمنة"],0],["كيف توازن دولة الإمارات بين التأثير العالمي والهوية الوطنية؟",["بحظر جميع المنتجات الأجنبية","بتعزيز التراث الوطني واللغة العربية إلى جانب الانفتاح على العالم","برفض التجارة مع الدول الأخرى"],1]],
  exit:"أكمل الجملة الآتية: «تكون العولمة عادلة عندما ___، وغير عادلة عندما ___».",
  copy:{facts:["تجلب العولمة فوائد مثل السلع الأرخص، وفرص العمل، والاستثمار، وانتشار الأفكار والتكنولوجيا.","ومن سلبياتها استغلال العمال، وفقدان الوظائف في بعض المجتمعات، والضرر البيئي، والتجانس الثقافي.","يتوقف الحكم على أخلاقية العولمة على وجهة النظر التي نأخذها في الحسبان؛ فهي كثيرًا ما تُوجِد رابحين وخاسرين معًا."]},
  next:"الحصة القادمة: نتابع الوحدة الأولى باستكشاف عدم المساواة في الدخل وأهميتها من الناحية الأخلاقية."
 },
 {
  id:"l3", lesson:3, title:"ما عدم المساواة في الدخل؟", unit:"الوحدة الأولى: الأخلاق والاقتصاد العالمي", art:"fair",
  dna:"مراجعة: في جملة واحدة، اذكر فائدة واحدة وسلبية واحدة للعولمة. ثم فكّر: لو تقاسم عشرة أشخاص كعكة وأخذ أحدهم نصفها، فهل يكون ذلك عادلًا؟ اكتب ما الذي يجعل القسمة عادلة أو غير عادلة.",
  dnaQs:["اذكر فائدة واحدة وسلبية واحدة للعولمة.","لو أخذ شخص واحد من عشرة نصف الكعكة، فهل يكون ذلك عادلًا؟","ما الذي يجعل القسمة عادلة أو غير عادلة؟"],
  dnaHint:"قد تكون الفائدة سلعًا أرخص أو وظائف جديدة، وقد تكون السلبية أجورًا متدنية أو ضررًا بيئيًا. أما بالنسبة إلى الكعكة، فالإجابة القوية تدرك أن «العادل» لا يعني دائمًا «المتساوي»: فقد يتوقف ذلك على مَن خبز الكعكة، أو مَن هو الأشد جوعًا، أو ما إذا كان الجميع قد اتفقوا على القواعد مسبقًا.",
  intentions:["أن أفهم ما عدم المساواة في الدخل وكيف يمكن قياسها.","أن أستكشف أسباب عدم المساواة في الدخل ونتائجها، داخل الدول وفيما بينها.","أن أقيّم الفرق بين المساواة والإنصاف، وما قد يبدو عليه التوزيع العادل للدخل."],
  criteria:["أستطيع أن أعرّف عدم المساواة في الدخل وأشرح كيف تُقاس (مثل معامل جيني).","أستطيع أن أشرح أسباب عدم المساواة في الدخل ونتائجها مع أمثلة.","أستطيع أن أقيّم آراء مختلفة حول ما يجعل توزيع الدخل عادلًا."],
  concept:{key:"العدالة", related:"الإنصاف، التنمية", soi:"تثير عدم المساواة في الدخل أسئلة أخلاقية حول العدالة وتكافؤ الفرص ومسؤولياتنا تجاه الآخرين في المجتمع وفي أنحاء العالم.", context:"العدالة والتنمية — استكشاف كيفية توزيع الثروة والفرص، وما يدين به المجتمع العادل لأفراده.", uae:"القيم الإسلامية في العدالة الاجتماعية ورعاية المحتاجين، ومنها الزكاة والصدقة؛ وبرامج الدعم الاجتماعي في دولة الإمارات ومبادرات مثل المساعدات الإنسانية العالمية التي تقدمها الدولة؛ مع روابط بمادتي الأفراد والمجتمعات (الاقتصاد) والرياضيات (البيانات والإحصاء)."},
  words:[["الدخل (Income)","المال الذي يُتلقى بانتظام، كالأجور من العمل أو العوائد من الاستثمارات."],["عدم المساواة (Inequality)","توزيع غير متساوٍ لشيء ما، كالدخل أو الثروة أو الفرص، بين الأفراد أو الفئات."],["معامل جيني (Gini coefficient)","مقياس لعدم المساواة في الدخل يتراوح من 0 (يحصل الجميع على الدخل نفسه تمامًا) إلى 1 (يحصل شخص واحد على الدخل كله)."],["الإنصاف (Equity)","العدالة في معاملة الناس، وقد تعني تقديم دعم أكبر لمن هم في أشد الحاجة إليه."],["الفقر (Poverty)","حالة عدم امتلاك ما يكفي من المال أو الموارد لتلبية الاحتياجات الأساسية."],["الحراك الاجتماعي (Social mobility)","قدرة الناس على الانتقال بين مستويات الدخل أو المستويات الاجتماعية المختلفة خلال حياتهم."]],
  task1:{title:"مهمة البحث", mins:20, criterion:"المعيار B — البحث والاستقصاء", steps:["اختر دولتين بمستويين مختلفين من عدم المساواة في الدخل (استخدم مصدرًا موثوقًا مثل البنك الدولي أو برنامج الأمم المتحدة الإنمائي).","ابحث في سبب واحد على الأقل لعدم المساواة في الدخل في كل دولة (مثل فرص الحصول على التعليم، ونوع الوظائف المتاحة، والأنظمة الضريبية، والعوامل التاريخية).","سجّل: كيف تُقاس عدم المساواة في مصادرك، ونتيجة واحدة لعدم المساواة في كل دولة.","دوّن سياسة أو برنامجًا واحدًا تستخدمه إحدى الدولتين للحد من عدم المساواة أو الفقر."], prompts:["الدولتان اللتان اخترتهما ومصادري","كيف تُقاس عدم المساواة في مصادري","سبب واحد ونتيجة واحدة لعدم المساواة في كل دولة","سياسة أو برنامج واحد يُستخدم للحد من عدم المساواة أو الفقر"], success:"الإجابات القوية تستخدم مقياسًا معترفًا به (مثل معامل جيني) من مصدر موثوق ومؤرَّخ، وتتجنب الأحكام العامة الشاملة على شعب بأكمله. ومن الأسباب الجيدة: عدم تكافؤ فرص الحصول على تعليم جيد، والفروق بين الوظائف عالية المهارة ومنخفضة المهارة، وأنظمة الضرائب والرعاية الاجتماعية. ومن النتائج الجيدة: تراجع الحراك الاجتماعي، والتفاوت في الصحة، والتوتر الاجتماعي. وللوصول إلى أعلى مستوى، اشرح سياسة حقيقية (مثل التعليم المجاني، أو قوانين الحد الأدنى للأجور، أو مدفوعات الدعم الاجتماعي) وعلّق على مدى فاعليتها المحتملة."},
  task2:{title:"مهمة القراءة والكتابة", mins:25, criterion:"المعيار C — التواصل", extract:"طالبان موهوبان بالقدر نفسه. يلتحق أحدهما بمدرسة ذات تمويل جيد، ويحصل على دروس خصوصية، ولديه مكان هادئ للدراسة في المنزل. أما الآخر فيلتحق بمدرسة تفتقر إلى الموارد، ويعمل بدوام جزئي لإعالة أسرته. وبعد سنوات، يصبح دخلاهما مختلفين جدًا.", steps:["في فقرة منظمة (جملة افتتاحية، شرح، مثال، خاتمة)، اشرح كيف يُظهر المقتطف العلاقة بين الفرص وعدم المساواة في الدخل.","استخدم ثلاث كلمات على الأقل من بنك الكلمات (مثل عدم المساواة، الإنصاف، الحراك الاجتماعي) استخدامًا دقيقًا.","اختم بشرح أيهما الاستجابة الأكثر عدلًا: المساواة أم الإنصاف، ولماذا."], model:"يبيّن المقتطف أن عدم المساواة في الدخل كثيرًا ما تنبع من عدم تكافؤ الفرص، لا من الفروق في الموهبة أو الجهد. فمع أن الطالبين متساويان في القدرة، يستفيد أحدهما من موارد يفتقر إليها الآخر، مما يحدّ من الحراك الاجتماعي للطالب الثاني ويؤدي إلى دخلين مختلفين جدًا لاحقًا في الحياة. ولن تؤدي معاملة الطالبين بالتساوي، بتقديم دعم متطابق لهما من الآن فصاعدًا، إلى تصحيح الحرمان القائم أصلًا. وأرى أن الإنصاف هو الاستجابة الأكثر عدلًا، لأن تقديم دعم إضافي للطالب الذي يواجه عوائق أكثر، مثل إتاحة الدروس الخصوصية أو أماكن الدراسة، يمنح كليهما فرصة عادلة حقًا لبلوغ أقصى إمكاناتهما.", rubric:[["1–2","بنية محدودة؛ استخدام قليل أو معدوم للمفردات الرئيسة."],["3–4","بنية فقرة أساسية؛ استخدام مصطلح رئيس واحد، وربما بصورة غير دقيقة."],["5–6","بنية فقرة واضحة؛ استخدام 2–3 مصطلحات رئيسة بدقة في معظم الأحيان؛ محاولة للتمييز بين المساواة والإنصاف."],["7–8","فقرة محكمة البنية؛ استخدام 3 مصطلحات رئيسة أو أكثر بدقة؛ تمييز واضح بين المساواة والإنصاف وحكم مبرر تبريرًا جيدًا."]], starters:["يبيّن المقتطف أن عدم المساواة في الدخل مرتبطة بـ ___.","مع أن الطالبين موهوبان بالقدر نفسه، فإن ___.","يحدّ ذلك من الحراك الاجتماعي لأن ___.","أرى أن الإنصاف / المساواة أكثر عدلًا لأن ___."]},
  task3:{title:"مهمة المشروع", mins:"حصتان", criterion:"المعيار D — التفكير الناقد", name:"مقترح سياسات لمجتمع أكثر عدلًا", steps:["في مجموعات من 3–4 طلاب، أنتم مستشارون لحكومة دولة خيالية تعاني ارتفاعًا في عدم المساواة في الدخل.","اقترحوا سياستين للحد من عدم المساواة في الدخل أو لزيادة الحراك الاجتماعي (مثل التعليم، أو التدريب، أو الحد الأدنى للأجور، أو الدعم الاجتماعي).","لكل سياسة، اشرحوا مَن تساعد، وكيف ستُموَّل، وسلبية أو اعتراضًا واحدًا محتملًا عليها.","اشرحوا المبدأ الأخلاقي (المساواة، الإنصاف، الحاجة، مكافأة الجهد) الذي تستند إليه كل سياسة.","اعرضوا مقترحكم على الصف في إحاطة مدتها 3 دقائق، واستخدموا مفردات بنك الكلمات في عرضكم."], rubric:[["1–2","سياسات مبهمة؛ تبرير أو تفكير أخلاقي محدود."],["3–4","سياسات أساسية بتفاصيل محدودة؛ ذكر السلبيات دون استكشافها."],["5–6","سياسات واضحة وواقعية؛ شرح مَن تساعد وما سلبياتها؛ تحديد المبدأ الأخلاقي."],["7–8","سياسات محكمة التصميم وواقعية؛ معالجة مدروسة للسلبيات والتمويل؛ تفكير أخلاقي عميق ومقنع."]]},
  game:{type:"sort", title:"مساواة أم إنصاف؟", prompt:"صنّف كل مثال: هل يُظهر المساواة (يحصل الجميع على الشيء نفسه) أم الإنصاف (دعم يتناسب مع الحاجة)؟", bins:["المساواة (الشيء نفسه للجميع)","الإنصاف (بحسب الحاجة)"], items:[["يحصل كل طالب على الكتاب المدرسي نفسه",0],["يحصل طالب يعاني ضعفًا في البصر على مواد بخط كبير",1],["يدفع الجميع الرسوم الثابتة نفسها مقابل خدمة ما",0],["تحصل الأسر ذات الدخل المنخفض على دعم إضافي لتكاليف المدرسة",1],["يحصل كل موظف في الفريق على مكافأة متطابقة",0],["تُقدَّم منحة دراسية للطلاب الموهوبين غير القادرين على دفع الرسوم",1],["لكل مواطن صوت واحد في الانتخابات",0],["تُقدَّم دروس تقوية إضافية للطلاب المتأخرين دراسيًا",1]]},
  quiz:[["ما عدم المساواة في الدخل؟",["توزيع غير متساوٍ للدخل بين الأفراد أو الفئات","أن يكسب الجميع المبلغ نفسه تمامًا","ضريبة تُدفع على الدخل"],0],["على معامل جيني، ماذا تعني الدرجة 0؟",["يحصل شخص واحد على الدخل كله","يحصل الجميع على الدخل نفسه تمامًا","لا يوجد اقتصاد في الدولة"],1],["ما الفرق بين المساواة والإنصاف؟",["يعنيان الشيء نفسه تمامًا","الإنصاف يعني عدم تقديم أي دعم لأحد","المساواة تمنح الجميع الشيء نفسه؛ والإنصاف يجعل الدعم متناسبًا مع الحاجة"],2],["ما معنى «الحراك الاجتماعي»؟",["الانتقال من منزل إلى آخر كثيرًا","استخدام وسائل التواصل الاجتماعي أثناء التنقل","قدرة الناس على الانتقال بين مستويات الدخل أو المستويات الاجتماعية خلال حياتهم"],2],["أي مما يلي سبب شائع لعدم المساواة في الدخل؟",["عدم تكافؤ فرص الحصول على تعليم جيد","امتلاك الجميع المهارات نفسها","أجور متطابقة لجميع الوظائف"],0],["في المقتطف، لماذا ينتهي الأمر بالطالبين إلى دخلين مختلفين؟",["أحد الطالبين أكثر موهبة بكثير","حصلا على فرص وموارد غير متكافئة","أحد الطالبين لم يرغب في العمل"],1],["أي العبادات الإسلامية ترتبط بالحد من الفقر؟",["الزكاة، وهي عطاء خيري واجب","فرض فوائد مرتفعة على القروض","الاحتفاظ بالثروة كلها لنفسك"],0],["أي مما يلي نتيجة محتملة لارتفاع عدم المساواة في الدخل؟",["زيادة التوتر الاجتماعي وتراجع الحراك الاجتماعي","حصول الجميع على الفرص نفسها","انعدام الفقر تمامًا"],0]],
  exit:"في جملة واحدة، اشرح ما إذا كنت ترى أن المجتمع العادل يحتاج إلى دخول متساوية، أم إلى فرص متكافئة، أم إلى كليهما.",
  copy:{facts:["عدم المساواة في الدخل هي التوزيع غير المتساوي للدخل بين الأفراد أو الفئات، ويمكن قياسها باستخدام معامل جيني (0 = مساواة تامة، 1 = عدم مساواة تامة).","من أسبابها عدم تكافؤ فرص التعليم، والفروق في الوظائف والمهارات، وأنظمة الضرائب والرعاية الاجتماعية؛ ومن نتائجها الفقر، وتراجع الحراك الاجتماعي، والتوتر الاجتماعي.","المساواة تعني معاملة الجميع بالطريقة نفسها؛ والإنصاف يعني جعل الدعم متناسبًا مع الحاجة. وتحث القيم الإسلامية، مثل الزكاة، على رعاية المحتاجين."]},
  next:"الحصة القادمة: نتابع الوحدة الأولى باستكشاف التجارة العادلة وكيف تسعى إلى جعل التجارة العالمية أكثر عدلًا."
 },
 {
  id:"l4", lesson:4, title:"ما التجارة العادلة؟", unit:"الوحدة الأولى: الأخلاق والاقتصاد العالمي", art:"community",
  dna:"مراجعة: في جملة واحدة، اشرح الفرق بين المساواة والإنصاف. ثم فكّر: يحصل مزارع الكاكاو على حصة صغيرة جدًا فقط من السعر الذي تدفعه ثمنًا للوح الشوكولاتة. اكتب مَن تظن أنه يحصل على الباقي، وهل يبدو ذلك عادلًا.",
  dnaQs:["في جملة واحدة، ما الفرق بين المساواة والإنصاف؟","إذا كان مزارع الكاكاو يحصل على حصة صغيرة فقط، فمَن تظن أنه يحصل على الباقي؟","هل يبدو ذلك عادلًا؟ لماذا أو لماذا لا؟"],
  dnaHint:"المساواة تعني أن يحصل الجميع على الشيء نفسه؛ والإنصاف يعني أن يتناسب الدعم مع الحاجة. ويُقسَّم باقي سعر الشوكولاتة بين المصنّعين، وشركات النقل، والعلامات التجارية، والمعلنين، وتجار التجزئة، والضرائب. والإجابة المتأملة تتساءل عمّا إذا كان المزارع، الذي يؤدي كثيرًا من أشق الأعمال، يحصل على مكافأة عادلة.",
  intentions:["أن أفهم ما التجارة العادلة وكيف تعمل شهادة التجارة العادلة.","أن أستكشف كيف تسعى التجارة العادلة إلى دعم المنتجين في الدول النامية.","أن أقيّم نقاط القوة والقيود في التجارة العادلة بوصفها استجابة للتجارة العالمية غير العادلة."],
  criteria:["أستطيع أن أشرح ما التجارة العادلة، بما في ذلك الحد الأدنى للأسعار والعلاوة الاجتماعية.","أستطيع أن أصف كيف يمكن أن تفيد التجارة العادلة المنتجين ومجتمعاتهم.","أستطيع أن أقيّم نقاط القوة والقيود في التجارة العادلة بتفكير متوازن."],
  concept:{key:"العدالة", related:"العدل، التفاعلات العالمية", soi:"تتحدى التجارة العادلة العلاقات التجارية الجائرة من خلال السعي إلى أسعار عادلة وظروف عمل لائقة وتنمية مستدامة للمنتجين.", context:"العدالة والتنمية — استكشاف كيف يمكن لقواعد التجارة وخيارات المستهلكين أن تعزز العدالة للمنتجين أو تقوّضها.", uae:"التعاليم الإسلامية في الصدق والعدل في التعامل التجاري وإعطاء العمال حقوقهم (توجيه النبي ﷺ بإعطاء الأجير أجره قبل أن يجف عرقه)؛ والهوية التاريخية لدولة الإمارات بوصفها أمة تجارية؛ مع روابط بمادتي الأفراد والمجتمعات (الاقتصاد) والتصميم (وسم المنتجات)."},
  words:[["التجارة العادلة (Fair trade)","نهج تجاري يسعى إلى منح المنتجين في الدول النامية أسعارًا عادلة وظروف عمل لائقة وشروط تجارة أفضل."],["المنتِج (Producer)","شخص أو منظمة تزرع السلع أو تصنعها، مثل المزارع أو الحرفي."],["الحد الأدنى للسعر (Minimum price)","سعر مضمون يُدفع للمنتجين ويهدف إلى تغطية تكاليفهم، حتى إذا انخفضت أسعار السوق."],["العلاوة (Premium)","مبلغ إضافي من المال يُدفع فوق السعر، يستثمره المنتجون في مجتمعاتهم أو أعمالهم."],["الاعتماد أو منح الشهادة (Certification)","عملية رسمية تتحقق من أن المنتج يستوفي معايير متفقًا عليها، ويُشار إليها بملصق أو علامة."],["التعاونية (Cooperative)","منظمة يملكها ويديرها أعضاؤها بصورة مشتركة، مثل مجموعة من المزارعين، ويتقاسمون منافعها."]],
  task1:{title:"مهمة البحث", mins:20, criterion:"المعيار B — البحث والاستقصاء", steps:["اختر منتجًا واحدًا شائع التداول وفق التجارة العادلة (مثل القهوة، أو الكاكاو، أو الموز، أو الشاي، أو القطن، أو السكر).","ابحث في كيفية عمل التجارة العادلة لهذا المنتج مستخدمًا مصدرين موثوقين على الأقل (مثل مؤسسة التجارة العادلة «Fairtrade Foundation»، أو المنظمة العالمية للتجارة العادلة).","سجّل: المعايير التي يجب أن يستوفيها المنتجون، والغرض من الحد الأدنى للسعر والعلاوة، ومثالًا واحدًا على كيفية استخدام العلاوة.","دوّن انتقادًا واحدًا أو قيدًا واحدًا على التجارة العادلة لهذا المنتج."], prompts:["المنتج الذي اخترته ومصدراي","المعايير التي يجب أن يستوفيها المنتجون","الغرض من الحد الأدنى للسعر والعلاوة، مع مثال واحد على استخدام العلاوة","انتقاد واحد أو قيد واحد"], success:"الإجابات القوية تشرح الغرض من الحد الأدنى للسعر (شبكة أمان عند انخفاض أسعار السوق) والعلاوة (مال إضافي تقرر مجموعات المنتجين كيفية استثماره، كما في المدارس أو المياه النظيفة أو معدات زراعية أفضل). ومن الانتقادات الجيدة: أن تكاليف الحصول على الشهادة قد تكون صعبة على أفقر المزارعين؛ وأن جزءًا فقط من المنتج قد يُباع وفق شروط التجارة العادلة؛ وأن منتجات التجارة العادلة قد تكلّف المستهلكين أكثر. وللوصول إلى أعلى مستوى، استخدم مصدرين موثوقين وقدّم مثالًا محددًا وحقيقيًا على استخدام العلاوة."},
  task2:{title:"مهمة القراءة والكتابة", mins:25, criterion:"المعيار C — التواصل", extract:"تنضم تعاونية مزارعين تزرع القهوة في الجبال إلى برنامج للتجارة العادلة. وعندما تنخفض أسعار القهوة العالمية انخفاضًا حادًا، يظلون يحصلون على الحد الأدنى للسعر. ويصوّتون على استخدام علاوتهم في حفر بئر ماء وشراء معدات تحسّن جودة محصولهم.", steps:["في فقرة منظمة (جملة افتتاحية، شرح، مثال، خاتمة)، اشرح كيف تفيد التجارة العادلة التعاونية الواردة في المقتطف.","استخدم ثلاث كلمات على الأقل من بنك الكلمات (مثل التعاونية، الحد الأدنى للسعر، العلاوة) استخدامًا دقيقًا.","اختم بتقييم قيد واحد على التجارة العادلة لم يذكره المقتطف."], model:"يبيّن المقتطف كيف يمكن للتجارة العادلة أن تحمي المنتجين وتدعم التنمية طويلة الأمد في مجتمعاتهم. فلأن التعاونية تحصل على حد أدنى مضمون للسعر، يكون المزارعون محميين عندما تنخفض أسعار القهوة العالمية انخفاضًا حادًا، فيظلون قادرين على تغطية تكاليفهم والتخطيط للمستقبل. وإضافة إلى ذلك، تمنحهم العلاوة مالًا يستثمرونه في أولويات يختارونها بأنفسهم، مثل بئر ماء تفيد المجتمع كله ومعدات تحسّن جودة قهوتهم. غير أن أحد القيود هو أن الحصول على الشهادة قد يكون مكلفًا وصعب المتطلبات، ولذلك قد يجد أفقر المزارعين، ممن لا ينتمون إلى تعاونية منظمة، صعوبة في الانضمام إلى مثل هذه البرامج والاستفادة منها أصلًا.", rubric:[["1–2","بنية محدودة؛ استخدام قليل أو معدوم للمفردات الرئيسة."],["3–4","بنية فقرة أساسية؛ استخدام مصطلح رئيس واحد، وربما بصورة غير دقيقة."],["5–6","بنية فقرة واضحة؛ استخدام 2–3 مصطلحات رئيسة بدقة في معظم الأحيان؛ تحديد أحد القيود."],["7–8","فقرة محكمة البنية؛ استخدام 3 مصطلحات رئيسة أو أكثر بدقة؛ القيد ذو صلة ومشروح شرحًا جيدًا."]], starters:["تفيد التجارة العادلة التعاونية لأن ___.","يحمي الحد الأدنى للسعر المزارعين عندما ___.","تتيح لهم العلاوة أن ___.","غير أن أحد قيود التجارة العادلة هو ___."]},
  task3:{title:"مهمة المشروع", mins:"حصتان", criterion:"المعيار D — التفكير الناقد", name:"حملة توعية بالتجارة العادلة", steps:["في مجموعات من 3–4 طلاب، صمموا حملة توعية تساعد الطلاب والأسر في دولة الإمارات على فهم التجارة العادلة.","اختاروا منتجًا واحدًا من منتجات التجارة العادلة، واشرحوا بوضوح كيف تؤثر التجارة العادلة في الأشخاص الذين ينتجونه.","ضمّنوا معلومات متوازنة: فائدتين على الأقل وقيدًا واحدًا صريحًا للتجارة العادلة.","أعدّوا موردًا للحملة (مثل ملصق، أو نص لمقطع فيديو قصير، أو سلسلة منشورات على وسائل التواصل الاجتماعي)، واقترحوا إجراءً عمليًا واحدًا يمكن للناس اتخاذه.","اعرضوا حملتكم على الصف في عرض مدته 3 دقائق، واستخدموا مفردات بنك الكلمات في عرضكم."], rubric:[["1–2","الحملة مبهمة أو غير دقيقة؛ شرح محدود للتجارة العادلة."],["3–4","حملة أساسية بتفاصيل محدودة؛ معالجة من جانب واحد."],["5–6","حملة واضحة ودقيقة تتضمن فوائد وقيدًا؛ اقتراح إجراء عملي."],["7–8","حملة مقنعة ودقيقة ومتوازنة؛ شرح عميق للأثر في المنتجين؛ إجراء واقعي وموجّه توجيهًا جيدًا."]]},
  game:{type:"sort", title:"مبدأ من مبادئ التجارة العادلة أم لا؟", prompt:"صنّف كل عبارة: هل هي مبدأ من مبادئ التجارة العادلة، أم تتعارض معها؟", bins:["مبدأ من مبادئ التجارة العادلة","يتعارض مع التجارة العادلة"], items:[["دفع حد أدنى للسعر للمنتجين يهدف إلى تغطية تكاليفهم",0],["تشغيل الأطفال لخفض التكاليف",1],["دفع علاوة يمكن للمجتمعات استثمارها كما تختار",0],["دفع أقل مبلغ ممكن للمزارعين لتحقيق أقصى ربح",1],["دعم المزارعين لتشكيل تعاونيات ديمقراطية",0],["تشجيع الزراعة المستدامة بيئيًا",0],["تجاهل ظروف العمل غير الآمنة",1],["علاقات تجارية طويلة الأمد وشفافة مع المنتجين",0]]},
  quiz:[["ما الهدف الرئيس للتجارة العادلة؟",["جعل المنتجات أرخص ما يمكن","منح المنتجين أسعارًا عادلة وظروف عمل لائقة وشروط تجارة أفضل","وقف التجارة الدولية كلها"],1],["ما الغرض من الحد الأدنى للسعر في التجارة العادلة؟",["أن يكون شبكة أمان تهدف إلى تغطية تكاليف المنتجين عند انخفاض أسعار السوق","جعل المتاجر تفرض أسعارًا أعلى","دفع تكاليف الإعلان"],0],["فيمَ تُستخدم «العلاوة» في التجارة العادلة؟",["الدفع لصاحب المتجر","الإعلان عن المنتج","استثمار يختاره المنتجون، كما في مشروعات المجتمع أو معدات أفضل"],2],["ما «التعاونية»؟",["شركة كبيرة واحدة","إدارة حكومية","منظمة يملكها ويديرها أعضاؤها بصورة مشتركة، ويتقاسمون منافعها"],2],["علامَ تدل «شهادة» التجارة العادلة؟",["على أن المنتج يستوفي معايير التجارة العادلة المتفق عليها","على أن المنتج هو الأرخص المتاح","على أن المنتج صُنع في دولة الإمارات"],0],["في المقتطف، كيف استخدمت التعاونية علاوتها؟",["للدفع لعلامة تجارية مشهورة","لحفر بئر ماء وشراء معدات","لخفض سعر القهوة"],1],["أي مما يلي قيد حقيقي على التجارة العادلة؟",["تجعل المنتجين أفقر دائمًا","تمنع المزارعين من تشكيل مجموعات","قد يكون الحصول على الشهادة مكلفًا، فيجد أفقر المزارعين صعوبة في الانضمام"],2],["أي التعاليم الإسلامية يرتبط بالتجارة العادلة؟",["أعطوا الأجير أجره قبل أن يجف عرقه","اشترِ دائمًا المنتج الأرخص","يجب أن تقتصر التجارة على النطاق المحلي"],0]],
  exit:"اذكر منتجًا واحدًا من منتجات التجارة العادلة يمكنك اختياره بدلًا من منتج غير حاصل على الشهادة، واشرح مَن يساعد.",
  copy:{facts:["تسعى التجارة العادلة إلى منح المنتجين في الدول النامية أسعارًا عادلة وظروف عمل لائقة وشروط تجارة أفضل.","من سماتها الرئيسة الحد الأدنى للسعر (شبكة أمان) والعلاوة التي تستثمرها مجموعات المنتجين في مجتمعاتها أو أعمالها.","للتجارة العادلة قيود، مثل تكاليف الحصول على الشهادة وارتفاع الأسعار، لكنها تتيح للمستهلكين وسيلة لدعم تجارة أكثر عدلًا."]},
  next:"الحصة القادمة: نتابع الوحدة الأولى باستكشاف العواقب الأخلاقية لخياراتنا الاستهلاكية اليومية."
 },
 {
  id:"l5", lesson:5, title:"العواقب الأخلاقية لخياراتنا الاستهلاكية", unit:"الوحدة الأولى: الأخلاق والاقتصاد العالمي", art:"eye",
  dna:"مراجعة: في جملة واحدة، اشرح ما علاوة التجارة العادلة. ثم فكّر: في آخر مرة اشتريت فيها ملابس أو طعامًا أو جهازًا إلكترونيًا، ما الذي أثّر في اختيارك أكثر من غيره (السعر، العلامة التجارية، الجودة، الأصدقاء، الإعلانات، الأخلاق)؟ اكتب أهم سببين.",
  dnaQs:["في جملة واحدة، ما علاوة التجارة العادلة؟","ما أهم سببين لآخر شيء اشتريته؟","هل كان للأخلاق (الناس أو الكوكب) أي دور في اختيارك؟"],
  dnaHint:"علاوة التجارة العادلة مال إضافي يُدفع فوق السعر، تستثمره مجموعات المنتجين في مجتمعاتها. ومعظم الناس يختارون بناءً على السعر أو العلامة التجارية أو الجودة. ولا بأس بالإجابة الصادقة: فالهدف هو أن نلاحظ كم نادرًا ما نفكر فيمن صنع المنتج وفي أثره على الكوكب.",
  intentions:["أن أفهم المقصود بالاستهلاك الأخلاقي وعواقب الخيارات الاستهلاكية.","أن أستكشف كيف تؤثر الخيارات الاستهلاكية في العمال والمجتمعات والبيئة عبر سلاسل التوريد العالمية.","أن أقيّم قوة المستهلكين الأفراد وحدودها في إحداث تغيير أخلاقي."],
  criteria:["أستطيع أن أشرح معنى الاستهلاك الأخلاقي مع أمثلة.","أستطيع أن أحلل العواقب الاجتماعية والبيئية لخيار استهلاكي على امتداد سلسلة التوريد.","أستطيع أن أقيّم مقدار المسؤولية التي يتحملها كل من الأفراد والشركات والحكومات عن الاستهلاك الأخلاقي."],
  concept:{key:"المسؤولية", related:"العواقب، الاستدامة", soi:"لكل عملية شراء عواقب على الناس والكوكب، ولذلك يتشارك المستهلكون المسؤولية عن آثار الاقتصاد العالمي.", context:"العولمة والاستدامة — استكشاف كيف ترتبط خيارات الأفراد بظروف العمل والآثار البيئية في أنحاء العالم.", uae:"التعاليم الإسلامية التي تنهى عن الهدر والتبذير (الإسراف)، ودور الإنسان خليفةً في الأرض؛ واهتمام دولة الإمارات بالاستدامة، ومن ذلك «عام الاستدامة» 2023 ومبادرة الإمارات للحياد المناخي 2050؛ مع روابط بمادتي العلوم (الأثر البيئي) والتصميم (دورة حياة المنتج)."},
  words:[["المستهلك (Consumer)","شخص يشتري السلع أو الخدمات لاستخدامه الخاص."],["الاستهلاك الأخلاقي (Ethical consumerism)","اختيار المنتجات والخدمات التي تقلل الضرر بالناس والحيوانات والبيئة إلى أدنى حد."],["الموضة السريعة (Fast fashion)","ملابس رخيصة تُنتَج بسرعة وبكميات كبيرة لمواكبة أحدث الصيحات، وغالبًا ما تُلبس لمدة قصيرة فقط."],["المقاطعة (Boycott)","الامتناع عن الشراء من شركة ما أو استخدام منتج ما، بوصف ذلك شكلًا من أشكال الاحتجاج."],["الاستدامة (Sustainability)","تلبية احتياجات الحاضر دون الإضرار بقدرة الأجيال القادمة على تلبية احتياجاتها."],["النزعة الاستهلاكية (Consumerism)","ثقافة أو اعتقاد بأن شراء مزيد من السلع والخدمات أمر مرغوب فيه ويؤدي إلى السعادة."]],
  task1:{title:"مهمة البحث", mins:20, criterion:"المعيار B — البحث والاستقصاء", steps:["اختر قضية استهلاكية واحدة (مثل الموضة السريعة، أو النفايات الإلكترونية، أو البلاستيك أحادي الاستخدام، أو هدر الطعام، أو معادن النزاعات في الأجهزة الإلكترونية).","ابحث فيها مستخدمًا مصدرين موثوقين على الأقل.","سجّل: العواقب الاجتماعية (على العمال أو المجتمعات) والعواقب البيئية لهذه القضية.","حدد إجراءً واحدًا يمكن للمستهلكين اتخاذه، وإجراءً واحدًا اتخذته شركة أو حكومة لمعالجتها."], prompts:["القضية التي اخترتها ومصدراي","العواقب الاجتماعية على العمال أو المجتمعات","العواقب البيئية","إجراء واحد يمكن للمستهلكين اتخاذه، وإجراء واحد اتخذته شركة أو حكومة"], success:"الإجابات القوية تربط بوضوح بين سلوك استهلاكي وعاقبة حقيقية في موضع آخر من سلسلة التوريد. ومن الأمثلة المعروفة انهيار مصنع «رانا بلازا» في بنغلاديش عام 2013، الذي لقي فيه أكثر من ألف عامل في صناعة الملابس حتفهم، وأدى إلى اتفاقيات جديدة لسلامة المباني في صناعة الملابس. وتميّز الإجابات القوية بين الإجراء الفردي (مثل شراء قطع أقل وأعلى جودة، والإصلاح، وإعادة التدوير) والإجراء على مستوى النظام (مثل القوانين ومعايير القطاع). وللوصول إلى أعلى مستوى، استخدم مصدرين موثوقين وقيّم مدى فاعلية هذه الإجراءات."},
  task2:{title:"مهمة القراءة والكتابة", mins:25, criterion:"المعيار C — التواصل", extract:"يرى مراهق إعلانًا على الإنترنت عن قميص عصري ثمنه أقل من ثمن وجبة طعام. فيشتري خمسة منه بألوان مختلفة، ويلبس كلًا منها بضع مرات فقط، ثم يرميها عندما تتغير الصيحة بعد بضعة أشهر.", steps:["في فقرة منظمة (جملة افتتاحية، شرح، مثال، خاتمة)، حلّل العواقب الأخلاقية لخيارات المراهق.","استخدم ثلاث كلمات على الأقل من بنك الكلمات (مثل الموضة السريعة، الاستدامة، النزعة الاستهلاكية) استخدامًا دقيقًا.","اختم بتقييم مقدار المسؤولية التي يتحملها المراهق، مقارنةً بالعلامة التجارية والحكومة."], model:"تُعدّ خيارات المراهق مثالًا نموذجيًا على الموضة السريعة، ولها عواقب أخلاقية تمتد إلى ما هو أبعد من المتجر بكثير. فمثل هذا السعر المنخفض قد يشير إلى أن العمال في موضع ما من سلسلة التوريد ربما يتقاضون أجورًا زهيدة جدًا أو يعملون في ظروف سيئة، كما أن إنتاج الملابس والتخلص منها سريعًا يهدر المياه والطاقة والمواد، وهو ما يتعارض مع مبدأ الاستدامة. ويعكس الإعلان أيضًا ثقافة النزعة الاستهلاكية التي تشجع الناس على شراء ما يزيد على حاجتهم. وفي رأيي، يتحمل المراهق بعض المسؤولية، لأنه يستطيع أن يختار شراء أقل والاحتفاظ بالملابس مدة أطول؛ غير أن العلامات التجارية تتحمل مسؤولية أكبر عن طريقة صنع منتجاتها وتسويقها، والحكومات مسؤولة عن سن القوانين التي تحمي العمال والبيئة وتطبيقها.", rubric:[["1–2","بنية محدودة؛ استخدام قليل أو معدوم للمفردات الرئيسة."],["3–4","بنية فقرة أساسية؛ استخدام مصطلح رئيس واحد، وربما بصورة غير دقيقة."],["5–6","بنية فقرة واضحة؛ استخدام 2–3 مصطلحات رئيسة بدقة في معظم الأحيان؛ مناقشة المسؤولية."],["7–8","فقرة محكمة البنية؛ استخدام 3 مصطلحات رئيسة أو أكثر بدقة؛ تحليل العواقب على الناس والكوكب؛ موازنة المسؤولية بطريقة متوازنة ومبررة."]], starters:["تُعدّ خيارات المراهق مثالًا على ___ لأن ___.","إحدى العواقب الاجتماعية هي ___.","إحدى العواقب البيئية هي ___، وهو ما يتعارض مع الاستدامة.","يتحمل المراهق بعض المسؤولية، لكن ___ أيضًا ___."]},
  task3:{title:"مهمة المشروع", mins:"حصتان", criterion:"المعيار D — التفكير الناقد", name:"دليل المتسوق الأخلاقي", steps:["في مجموعات من 3–4 طلاب، أعدّوا «دليل المتسوق الأخلاقي» للطلاب في دولة الإمارات.","اختاروا ثلاث فئات من المنتجات (مثل الملابس، أو الأجهزة الإلكترونية، أو الطعام، أو مستحضرات التجميل).","لكل فئة، اشرحوا مصدر قلق أخلاقيًا واحدًا، وقدّموا إجراءين عمليين وميسوري التكلفة يمكن للطلاب اتخاذهما.","ضمّنوا قسمًا قصيرًا يقيّم حدود الإجراء الفردي وما يجب على الشركات أو الحكومات فعله.","اعرضوا دليلكم على الصف في عرض مدته 3 دقائق، واستخدموا مفردات بنك الكلمات في عرضكم."], rubric:[["1–2","الدليل مبهم؛ المخاوف والإجراءات غير واضحة أو غير واقعية."],["3–4","دليل أساسي بتفاصيل محدودة؛ إجراءات عامة."],["5–6","دليل واضح بمخاوف دقيقة وإجراءات عملية؛ مراعاة حدود الإجراء الفردي."],["7–8","دليل عميق ودقيق وعملي؛ إجراءات واقعية للطلاب؛ تقييم مدروس لمسؤولية الفرد مقابل مسؤولية النظام."]]},
  game:{type:"sort", title:"خيار أخلاقي أم لا؟", prompt:"صنّف كل سلوك استهلاكي: هل هو خيار أخلاقي، أم خيار يُرجَّح أن يسبب ضررًا؟", bins:["خيار أكثر أخلاقية","يُرجَّح أن يسبب ضررًا"], items:[["إصلاح الهاتف بدلًا من استبداله",0],["شراء ملابس رخيصة عدة لارتداء كل منها مرة واحدة",1],["اختيار منتجات تحمل علامة معترفًا بها للتجارة العادلة",0],["رمي الأجهزة الإلكترونية القديمة مع النفايات العامة",1],["شراء ملابس مستعملة أو تبادلها مع الأصدقاء",0],["طلب طعام يزيد كثيرًا على حاجتك وهدره",1],["البحث في كيفية معاملة علامة تجارية لعمالها قبل الشراء",0],["شراء منتج لمجرد أن أحد المؤثرين روّج له",1]]},
  quiz:[["ما «الاستهلاك الأخلاقي»؟",["اختيار المنتجات التي تقلل الضرر بالناس والحيوانات والبيئة إلى أدنى حد","شراء أرخص منتج متاح","التسوق عبر الإنترنت فقط"],0],["ما «الموضة السريعة»؟",["ملابس للعدائين","ملابس مصممين باهظة الثمن تدوم سنوات كثيرة","ملابس رخيصة تُنتَج بسرعة لمواكبة الصيحات، وغالبًا ما تُلبس لمدة قصيرة فقط"],2],["ما «المقاطعة»؟",["نوع من الإعلانات","الامتناع عن الشراء من شركة ما أو عن منتج ما بوصف ذلك شكلًا من أشكال الاحتجاج","تخفيض على الملابس"],1],["ما معنى «الاستدامة»؟",["تلبية احتياجات الحاضر دون الإضرار بقدرة الأجيال القادمة على تلبية احتياجاتها","استخدام أكبر قدر ممكن من الموارد","صنع المنتجات بسرعة"],0],["أي حدث في عام 2013 أدى إلى اتفاقيات جديدة لسلامة المباني في صناعة الملابس؟",["افتتاح مركز تسوق جديد","انهيار مصنع «رانا بلازا» في بنغلاديش","عرض أزياء في باريس"],1],["أي المفاهيم الإسلامية ينهى عن الهدر والتبذير؟",["التعاون","الشورى","الإسراف"],2],["أي مما يلي هو الرأي الأكثر توازنًا بشأن المسؤولية عن الاستهلاك الأخلاقي؟",["المستهلكون وحدهم هم المسؤولون","الحكومات وحدها هي المسؤولة","يتشارك المستهلكون والشركات والحكومات جميعهم المسؤولية"],2],["أي إجراء يقلل الأثر البيئي للملابس على أفضل وجه؟",["شراء قطع أقل وأعلى جودة والاحتفاظ بها مدة أطول","شراء ملابس جديدة كل أسبوع","رمي الملابس عندما تتغير الصيحات"],0]],
  exit:"اكتب تغييرًا واحدًا يمكنك إجراؤه فعليًا على عاداتك في التسوق هذا الشهر، والأثر الذي سيحدثه.",
  copy:{facts:["الاستهلاك الأخلاقي يعني اختيار المنتجات التي تقلل الضرر بالناس والحيوانات والبيئة إلى أدنى حد.","للخيارات الاستهلاكية، مثل الموضة السريعة، عواقب على امتداد سلاسل التوريد العالمية تمس حقوق العمال والكوكب.","المسؤولية مشتركة: يستطيع المستهلكون الاختيار بحكمة، لكن على الشركات والحكومات أن تتحرك أيضًا. وينهى الإسلام عن الهدر (الإسراف)."]},
  next:"الحصة القادمة: نُكمل الوحدة الأولى باستكشاف الاستثمار المسؤول اجتماعيًا."
 },
 {
  id:"l6", lesson:6, title:"الاستثمار المسؤول اجتماعيًا", unit:"الوحدة الأولى: الأخلاق والاقتصاد العالمي", art:"business",
  dna:"اختبار مفردات الوحدة الأولى! عرّف كل مصطلح بأكبر قدر ممكن من الدقة: العولمة، الاعتماد المتبادل، عدم المساواة في الدخل، التجارة العادلة، الاستهلاك الأخلاقي. ثم فكّر: لو أُعطيت مالًا لتستثمره، فهل ستهتم بما تفعله الشركة، أم بمقدار الربح الذي تحققه فقط؟",
  dnaQs:["العولمة والاعتماد المتبادل — ما معنى كل منهما؟","عدم المساواة في الدخل، والتجارة العادلة، والاستهلاك الأخلاقي — ما معنى كل منها؟","لو استثمرت مالًا، فهل ستهتم بما تفعله الشركة، أم بالربح فقط؟"],
  dnaHint:"العولمة: الترابط والاعتماد المتبادل المتزايد بين الاقتصادات والشعوب. الاعتماد المتبادل: اعتماد بعضنا على بعض بحيث يؤثر التغير في أحدنا في الآخرين. عدم المساواة في الدخل: التوزيع غير المتساوي للدخل. التجارة العادلة: أسعار وظروف عادلة للمنتجين. الاستهلاك الأخلاقي: اختيار المنتجات التي تقلل الضرر إلى أدنى حد. أما سؤال الاستثمار، فالإجابة المتأملة تراعي الربح وأثر الشركة في الناس والكوكب معًا.",
  intentions:["أن أفهم ما الاستثمار المسؤول اجتماعيًا (SRI) وكيف يعمل.","أن أستكشف مناهج الاستثمار مثل الفرز الأخلاقي، ومعايير الحوكمة البيئية والاجتماعية والمؤسسية (ESG)، والاستثمار الإسلامي (المتوافق مع الشريعة).","أن أقيّم ما إذا كان المستثمرون يتحملون مسؤولية أخلاقية عمّا تدعمه أموالهم، جامعًا ما تعلمته عبر الوحدة الأولى."],
  criteria:["أستطيع أن أشرح ما الاستثمار المسؤول اجتماعيًا، بما في ذلك الفرز ومعايير ESG.","أستطيع أن أقارن بين مناهج مختلفة للاستثمار المسؤول، بما فيها مبادئ التمويل الإسلامي.","أستطيع أن أقيّم المسؤوليات الأخلاقية للمستثمرين وأربطها بأفكار من مختلف دروس الوحدة الأولى."],
  concept:{key:"المسؤولية", related:"الأخلاق، الاستدامة", soi:"يتشارك المستثمرون المسؤولية الأخلاقية عمّا تدعمه أموالهم، ويمكنهم استخدام الاستثمار لتعزيز اقتصاد عالمي أكثر عدلًا واستدامة.", context:"العولمة والاستدامة — استكشاف كيف تشكّل القرارات المالية الشركات والمجتمعات والبيئة.", uae:"مبادئ التمويل الإسلامي (تجنب الربا (الفائدة) والاستثمار في الأنشطة المحرّمة)، ودور دولة الإمارات مركزًا رائدًا للتمويل الإسلامي والصكوك، ومبادرة الإمارات للحياد المناخي 2050 ومبادرات التمويل الأخضر؛ مع روابط بمادة الأفراد والمجتمعات (إدارة الأعمال والاقتصاد)."},
  words:[["الاستثمار (Investment)","وضع المال في عمل تجاري أو مشروع أو أصل ما مع توقع تحقيق عائد مالي."],["الاستثمار المسؤول اجتماعيًا (Socially responsible investment – SRI)","الاستثمار بطريقة تراعي الآثار الاجتماعية والبيئية والأخلاقية، إلى جانب العوائد المالية."],["معايير الحوكمة البيئية والاجتماعية والمؤسسية (ESG)","معايير بيئية واجتماعية ومعايير حوكمة تُستخدم لتقييم مدى مسؤولية سلوك الشركة."],["الفرز الأخلاقي (Ethical screening)","إدراج الشركات في الاستثمار أو استبعادها منه بناءً على معايير أخلاقية، مثل تجنب الصناعات الضارة."],["المساهم (Shareholder)","شخص أو منظمة تملك أسهمًا (حصة في ملكية) في شركة ما."],["الاستثمار المتوافق مع الشريعة (Sharia-compliant investment)","استثمار يتبع المبادئ الإسلامية، مثل تجنب الفائدة (الربا) والصناعات المحرّمة."]],
  task1:{title:"مهمة البحث", mins:20, criterion:"المعيار A — المعرفة والفهم", steps:["اختر منهجًا واحدًا من مناهج الاستثمار المسؤول: الاستثمار وفق معايير ESG، أو الفرز الأخلاقي، أو الاستثمار المؤثر، أو السندات الخضراء، أو الاستثمار المتوافق مع الشريعة (بما في ذلك الصكوك).","ابحث فيه مستخدمًا مصدرين موثوقين على الأقل.","سجّل: كيف يعمل هذا المنهج، وما الذي يشمله أو يستبعده، ولماذا يختاره المستثمرون.","دوّن مثالًا واحدًا على تطبيق هذا المنهج عمليًا (ويُفضَّل أن يكون مرتبطًا بدولة الإمارات أو منطقة الخليج)، وانتقادًا واحدًا له."], prompts:["المنهج الذي اخترته ومصدراي","كيف يعمل، وما الذي يشمله أو يستبعده","لماذا يختاره المستثمرون، ومثال واحد على تطبيقه عمليًا","انتقاد واحد لهذا المنهج"], success:"الإجابات القوية تشرح المنهج بدقة: فعلى سبيل المثال، يتجنب الاستثمار المتوافق مع الشريعة الإقراض القائم على الفائدة وقطاعات مثل الكحول والقمار؛ ويقيّم الاستثمار وفق معايير ESG الشركات بناءً على العوامل البيئية والاجتماعية وعوامل الحوكمة؛ وتجمع السندات الخضراء الأموال لمشروعات بيئية. ومن الانتقادات الجيدة «الغسل الأخضر» (مبالغة الشركات في تصوير سلوكها المسؤول) وصعوبة قياس الأثر بصورة متسقة. وللوصول إلى أعلى مستوى، استخدم مصدرين موثوقين وقدّم مثالًا محددًا وحقيقيًا."},
  task2:{title:"مهمة القراءة والكتابة", mins:25, criterion:"المعيار C — التواصل", extract:"تأمّل في الوحدة الأولى: الحصة 1 (الاقتصاد والعولمة)، والحصة 2 (فوائد العولمة وسلبياتها)، والحصة 3 (عدم المساواة في الدخل)، والحصة 4 (التجارة العادلة)، والحصة 5 (الخيارات الاستهلاكية)، والحصة 6 (الاستثمار المسؤول اجتماعيًا).", steps:["اكتب فقرة منظمة (جملة افتتاحية، ثلاثة روابط، خاتمة) تشرح فيها كيف يمكن للأفراد التصرف بطريقة أخلاقية داخل الاقتصاد العالمي.","استخدم أربع كلمات على الأقل من بنك الكلمات في مختلف دروس الوحدة الأولى (أي حصة) استخدامًا دقيقًا.","اختم برأيك الخاص المبرر: مَن يملك القوة الأكبر لجعل الاقتصاد العالمي أكثر عدلًا — المستهلكون أم المستثمرون أم الشركات أم الحكومات؟"], model:"بيّنت هذه الوحدة أن خياراتنا الاقتصادية، بسبب العولمة والاعتماد المتبادل، تؤثر في الناس والبيئة إلى ما هو أبعد من حدود بلدنا بكثير. فبوصفنا مستهلكين، يمكننا ممارسة الاستهلاك الأخلاقي باختيار منتجات التجارة العادلة وتجنب الموضة السريعة، مما يدعم المنتجين ويساعد على الحد من الاستغلال (الحصتان 4–5). وبوصفنا مستثمرين في المستقبل، يمكننا اللجوء إلى الاستثمار المسؤول اجتماعيًا، مثل مناهج ESG أو المناهج المتوافقة مع الشريعة، لتوجيه الأموال نحو الشركات التي تعامل الناس بعدل وتحمي الكوكب (الحصة 6). وترتبط هذه الخيارات أيضًا بعدم المساواة في الدخل، لأن الأجور الأكثر عدلًا والاستثمار المسؤول يمكن أن يوسّعا الفرص بدلًا من تركيز الثروة (الحصة 3). وفي رأيي، تملك الحكومات القوة الأكبر، لأنها تسنّ القوانين التي يجب على جميع الشركات اتباعها؛ غير أن المستهلكين والمستثمرين يُوجِدون الطلب الذي يشجع الشركات على التغيير، ولذلك يتطلب التقدم الحقيقي أن يعمل الجميع معًا.", rubric:[["1–2","بنية محدودة؛ استخدام قليل أو معدوم للمفردات الرئيسة؛ لا روابط حقيقية."],["3–4","بنية فقرة أساسية؛ استخدام 1–2 من المصطلحات الرئيسة؛ روابط مبهمة."],["5–6","بنية فقرة واضحة؛ استخدام 3 مصطلحات رئيسة بدقة في معظم الأحيان؛ روابط معقولة بين الحصص."],["7–8","فقرة محكمة البنية؛ استخدام 4 مصطلحات رئيسة أو أكثر بدقة من حصص متعددة؛ روابط عميقة؛ خاتمة مبررة تبريرًا جيدًا."]], starters:["بسبب العولمة، فإن خياراتنا الاقتصادية ___.","بوصفنا مستهلكين، يمكننا أن ___.","بوصفنا مستثمرين، يمكننا أن ___، مثل ___.","في رأيي، تملك ___ القوة الأكبر لأن ___."]},
  task3:{title:"مهمة المشروع (عرض ختامي للوحدة)", mins:"حصتان", criterion:"المعيار D — التفكير الناقد", name:"عرض صندوق استثمار مسؤول", steps:["في مجموعات من 3–4 طلاب، تخيّلوا أنكم تديرون صندوق استثمار خياليًا للشباب في دولة الإمارات.","اكتبوا مجموعة واضحة من مبادئ الاستثمار لصندوقكم (ما ستستثمرون فيه، وما ستستبعدونه، ولماذا)، مستندين إلى معايير ESG و/أو الفرز الأخلاقي و/أو مبادئ التمويل الإسلامي.","اختاروا ثلاثة أنواع من الأعمال أو المشروعات التي سيدعمها صندوقكم (مثل الطاقة المتجددة، ومنتجي التجارة العادلة، والرعاية الصحية ميسورة التكلفة)، وبرّروا كل اختيار مستخدمين أفكارًا من مختلف دروس الوحدة الأولى.","حددوا مفاضلة واحدة يواجهها صندوقكم (مثل انخفاض العوائد على المدى القصير، أو خطر الغسل الأخضر)، واشرحوا كيف ستتعاملون معها.","اعرضوا صندوقكم على الصف في «عرض للمستثمرين» مدته 4 دقائق. ويصوّت الصف على الصندوق الأكثر إقناعًا والأكثر تبريرًا من الناحية الأخلاقية."], rubric:[["1–2","مبادئ استثمار مبهمة؛ ارتباط محدود بما تعلمه الطلاب في الوحدة."],["3–4","مبادئ واختيارات أساسية؛ تبرير محدود؛ ذكر المفاضلة دون معالجتها."],["5–6","مبادئ واضحة واستثمارات مختارة بعناية؛ تبرير باستخدام أفكار الوحدة؛ تحديد المفاضلة ومعالجتها."],["7–8","مبادئ عميقة ومتماسكة؛ تبرير مقنع للاستثمارات عبر حصص متعددة من الوحدة الأولى؛ تحليل مدروس للمفاضلة وإدارتها بواقعية."]]},
  game:{type:"sort", title:"بأي حصة ترتبط الفكرة؟", prompt:"صنّف كل فكرة ضمن الجزء الذي تنتمي إليه من الوحدة الأولى.", bins:["العولمة وعدم المساواة","التجارة العادلة والخيارات الاستهلاكية","الاستثمار المسؤول"], items:[["سلاسل التوريد التي تربط المنتجين والمستهلكين في دول كثيرة",0],["معامل جيني بوصفه مقياسًا لكيفية توزيع الدخل",0],["حد أدنى للسعر وعلاوة يُدفعان لتعاونية مزارعين",1],["إصلاح الهاتف بدلًا من شراء هاتف جديد",1],["تقييم الشركات وفق المعايير البيئية والاجتماعية ومعايير الحوكمة",2],["استبعاد صناعات مثل القمار من صندوق استثماري",2],["الإنصاف: جعل الدعم متناسبًا مع الحاجة",0],["تجنب الموضة السريعة للحد من الهدر",1]]},
  quiz:[["ما الاستثمار المسؤول اجتماعيًا (SRI)؟",["الاستثمار فقط في الشركات التي تحقق أعلى الأرباح","الاستثمار بطريقة تراعي الآثار الاجتماعية والبيئية والأخلاقية إلى جانب العوائد المالية","التبرع بالمال للجمعيات الخيرية دون عائد"],1],["إلامَ يشير الاختصار ESG؟",["الاقتصادي والاجتماعي والعالمي","الأخلاقي والمستدام والأخضر","البيئي والاجتماعي والحوكمة"],2],["ما «الفرز الأخلاقي»؟",["إدراج الشركات أو استبعادها بناءً على معايير أخلاقية","مشاهدة أفلام عن الأخلاق","التحقق من سعر سهم الشركة يوميًا"],0],["أي مما يلي مبدأ من مبادئ الاستثمار المتوافق مع الشريعة؟",["الاستثمار بكثافة في شركات القمار","تجنب الفائدة (الربا) والصناعات المحرّمة","فرض أعلى فائدة ممكنة"],1],["مَن «المساهم»؟",["شخص يعمل في متجر","موظف ضرائب حكومي","شخص أو منظمة تملك جزءًا من شركة من خلال الأسهم"],2],["ما «الغسل الأخضر»؟",["مبالغة شركة ما في تصوير مدى مسؤوليتها البيئية","تنظيف مصنع بمنتجات صديقة للبيئة","الاستثمار في الطاقة المتجددة"],0],["كيف يرتبط الاستثمار المسؤول بالتجارة العادلة والاستهلاك الأخلاقي؟",["لا يوجد أي ارتباط بينها","تستخدم الثلاثة الخيارات الاقتصادية لدعم معاملة أكثر عدلًا للناس والكوكب","جميعها قوانين حكومية"],1],["أي التزامات دولة الإمارات يرتبط بالاستثمار الأخضر؟",["إنهاء التجارة كلها","حظر الشركات الأجنبية","مبادرة الإمارات للحياد المناخي 2050"],2]],
  exit:"اكتب مبدأً واحدًا ستتبعه إذا استثمرت مالًا في المستقبل، واشرح من أي فكرة في الوحدة الأولى استمددته.",
  copy:{facts:["يراعي الاستثمار المسؤول اجتماعيًا الآثار الاجتماعية والبيئية والأخلاقية إلى جانب العوائد المالية، مستخدمًا أدوات مثل معايير ESG والفرز الأخلاقي.","يتجنب الاستثمار المتوافق مع الشريعة الفائدة (الربا) والصناعات المحرّمة؛ ودولة الإمارات مركز رائد للتمويل الإسلامي.","يتشارك المستهلكون والمستثمرون والشركات والحكومات جميعهم المسؤولية عن جعل الاقتصاد العالمي أكثر عدلًا واستدامة."]},
  next:"اكتملت الوحدة الأولى: الأخلاق والاقتصاد العالمي! ننتقل بعد ذلك إلى الوحدة الثانية من برنامج التربية الأخلاقية للصف العاشر."
 }
];
